__NUXT_JSONP__("/tw/westwood", (function(a){return {data:[{details:{slug:a,pageTitle:"Westwood 院區 | Mentor Language Institute",pageDescription:"Westwood是一個位於洛杉磯西側的活耀、獨特的地區。Westwood是UCLA附近有名的住宅區。",title:"Westwood 院區",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FUnc0XBR1eQI",subtitle:["Westwood是一個位於洛杉磯西側的活耀、獨特的地區。Westwood是UCLA附近有名的住宅區。Westwood 院區位於Wilshire Blvd及 Westwood Blvd交接處。到Wilshire Blvd及 Westwood Blvd主要的公車幹線只需要1分鐘。附近有許多商店、餐廳及大學生，是一個有名有趣又安全的地方，很受學生及上班族歡迎。"],landmark:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fsanta-monica.jpg",title:"公車20分鐘到Santa Monica"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fbeverly-hills.jpg",title:"公車10分鐘到 Beverly Hills"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Flos-angeles-skyline.jpg",title:"公車60分鐘到LA市區"}],gallery:{title:"Westwood院區的項面總覽",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002F10880-building.jpg",title:"位於建築物的一樓，不需搭乘電梯到教室。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffront-desk.jpg",title:"櫃台"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fclassroom.jpg",title:"教室"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fcomputer-room.jpg",title:"電腦教室"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fstudent-lounge.jpg",title:"學生休息室"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffree-space.jpg",title:"自由活動區"}]},location:{title:"地點",map_link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3305.4289041796537!2d-118.44512238478478!3d34.05851788060419!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bb7e2b42fadf%3A0xad96227841e11efb!2s10880+Wilshire+Blvd%2C+Los+Angeles%2C+CA+90024!5e0!3m2!1sen!2sus!4v1513884279258"},video:[{title:"1. 如何搭乘巴士前往MLI Westwood Campus",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV2zydV7aWvA"},{title:"2. 如何自駕前往MLI Westwood Campus",addspace:"\u003Cbr\u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F5FXkkyV3DZg"}],environment:{title:"環境",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fucla.jpg",title:"到UCLA的步行距離"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fhammer-museum.jpg",title:"LA最有名的博物館The Hammer Museum就在我們學院的旁邊。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-library.jpg",title:"學院後方有一個圖書館可以唸書。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fchevron-restaurant.jpg",title:"許多可負擔得起的餐廳"}]},accommodation:{title:"住宿",description:["我們提供寄宿家宿和宿舍兩個住宿类型選擇"],types:[{desc:["＜宿舍＞\u003Cbr \u002F\u003E宿舍有40間房間，可以步行或搭公車到學校。"],yt_link2:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV_eNdjw6Z1c"},{desc:["＜寄宿家庭＞"],other_desc:["寄宿家庭有助于增進學英語及學習美國文化的最佳機會。","\u003Ca href=\"\u002Ftw\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E 更多關於住宿資訊\u003C\u002Fa\u003E"]}]},courses:{title:"課程總覽",lists:["ESL 課程","TOEFL®(托福)","IELTS™(雅思)","口說對話課程","TOEIC®(多益)課程"]},message:{title:"來自Westwood院區的話",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-director.jpg",position:"來自校長的話",description:["Westwood學院位於鄰近UCLA的極佳位置。附近有很多地方可以拜訪，電影院、逛街及博物館。我們的TOEFL®課程非常受歡迎，因為許多學生想至大專院校唸書，我們的學費非常的合理。許多學生從其它學校轉來MLI!"]},dir:"\u002Fwestwood",path:"\u002Fwestwood\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:31.462Z",updatedAt:"2025-05-26T12:06:28.050Z"},lang:a}],fetch:{},mutations:void 0}}("tw")));